//autogenerated:yes
//nolint:revive,govet,errcheck
package development_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
	"github.com/stretchr/testify/require"
)

func TestEnum_ACTUATOR_TEST_GROUP(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.ACTUATOR_TEST_GROUP
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.ACTUATOR_TEST_GROUP_ROLL_TORQUE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.ACTUATOR_TEST_GROUP
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.ACTUATOR_TEST_GROUP_ROLL_TORQUE, dec)
	})
}
